const startJob = `-- name: StartJob :execrows
UPDATE jobs SET status = 'running', updated_at = now() WHERE id = $1 AND status = 'queued'
`

// Each transition happens once, so its webhook fires once however many times a job retries.
func (q *Queries) StartJob(ctx context.Context, id pgtype.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, startJob, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const startTimeline = `-- name: StartTimeline :exec
UPDATE assets SET timeline = jsonb_build_object('received', now()) WHERE id = $1
`

// Processing (re)starts: a fresh timeline, so a retry never shows the last attempt's stages.
func (q *Queries) StartTimeline(ctx context.Context, id pgtype.UUID) error {
	_, err := q.db.Exec(ctx, startTimeline, id)
	return err
}

const storedMinutes = `-- name: StoredMinutes :many
SELECT tenant_id::uuid, minutes::double precision FROM stored_minutes()
`

type StoredMinutesRow struct {
	TenantID pgtype.UUID `json:"tenant_id"`
	Minutes  float64     `json:"minutes"`
}

func (q *Queries) StoredMinutes(ctx context.Context) ([]StoredMinutesRow, error) {
	rows, err := q.db.Query(ctx, storedMinutes)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []StoredMinutesRow
	for rows.Next() {
		var i StoredMinutesRow
		if err := rows.Scan(&i.TenantID, &i.Minutes); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

