const videoStats = `-- name: VideoStats :one
SELECT count(*) AS total,
    count(*) FILTER (WHERE status IN ('ready', 'complete')) AS playable,
    count(*) FILTER (WHERE status IN ('waiting', 'processing')) AS processing,
    count(*) FILTER (WHERE status = 'errored') AS failed,
    (coalesce(sum(duration_seconds) FILTER (WHERE status IN ('ready', 'complete')), 0) / 60)::float8 AS minutes
FROM assets WHERE deleted_at IS NULL
`

type VideoStatsRow struct {
	Total      int64   `json:"total"`
	Playable   int64   `json:"playable"`
	Processing int64   `json:"processing"`
	Failed     int64   `json:"failed"`
	Minutes    float64 `json:"minutes"`
}

func (q *Queries) VideoStats(ctx context.Context) (VideoStatsRow, error) {
	row := q.db.QueryRow(ctx, videoStats)
	var i VideoStatsRow
	err := row.Scan(
		&i.Total,
		&i.Playable,
		&i.Processing,
		&i.Failed,
		&i.Minutes,
	)
	return i, err
}
